instruction: Debug the following C++ code that is supposed to print the elements of a 2D array but instead crashes without any clear error message. Also, enhance the code by adding functions to perform column and row major traversals of the 2D array.

response: Below is a safe, crash-free example that prints a 2D array and adds both row-major and column-major traversal functions. A very common cause of “crashes without clear errors” in 2D-array code is treating an `int**` as if it were a contiguous 2D array, or indexing past bounds.

### Fixed & enhanced C++ code
```cpp
#include <iostream>
#include <vector>

using std::cout;
using std::size_t;

void printRowMajor(const std::vector<std::vector<int>>& a) {
    if (a.empty() || a[0].empty()) return;

    const size_t rows = a.size();
    const size_t cols = a[0].size();

    // Optional: ensure rectangular matrix
    for (const auto& row : a) {
        if (row.size() != cols) {
            throw std::runtime_error("Non-rectangular 2D array");
        }
    }

    for (size_t r = 0; r < rows; ++r) {
        for (size_t c = 0; c < cols; ++c) {
            cout << a[r][c] << ' ';
        }
        cout << '\n';
    }
}

void printColumnMajor(const std::vector<std::vector<int>>& a) {
    if (a.empty() || a[0].empty()) return;

    const size_t rows = a.size();
    const size_t cols = a[0].size();

    for (const auto& row : a) {
        if (row.size() != cols) {
            throw std::runtime_error("Non-rectangular 2D array");
        }
    }

    for (size_t c = 0; c < cols; ++c) {
        for (size_t r = 0; r < rows; ++r) {
            cout << a[r][c] << ' ';
        }
        cout << '\n';
    }
}

int main() {
    // Example 2D array
    std::vector<std::vector<int>> arr {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    cout << "Row-major traversal:\n";
    printRowMajor(arr);

    cout << "\nColumn-major traversal:\n";
    printColumnMajor(arr);
}
```

